'use strict';
// Phase 1c-b1 — PARITY GATE A: form/bootstrap parity + stale-artifact guard + deterministic inverse.
// Run: node catalog-form-bundle.test.js
//
// SCOPE (claim-accuracy — same discipline as 1c-a's "mutation-proven" wording): this gate generates via
// catalogSnapshot() → buildCatalogV2(), which slices the FORM, so it proves
// `rebuildFormMenu(buildCatalogV2(form)) == form` — i.e. the bundle the BOOTSTRAP produces equals today's
// hard-coded form MENU byte-identical incl. EVERY field AND order, both brands (dish array, category
// order/labels/subcats/layout, La Musa VARIANT_ITEMS, the HAS_PHOTO set, the X. Pizza PICKUP_ONLY /
// WEEKEND_ONLY gate cats), the COMMITTED artifact is not stale, generation is a deterministic inverse,
// and it is non-vacuous (mutating the snapshot changes the bundle). It does NOT prove the artifact matches
// the LIVE catalog store — that (the sole real catalog-store proof, load-bearing) is the EMULATOR test
// test/catalog-generation.emulator.test.js, which reads via the real getRestaurantMenu + a catalog-only
// sentinel. A wrong/reordered bundle here = the wrong customer menu once 1c-b3 flips the form to read it.
const assert = require('assert');
const { readFileSync } = require('fs');
const { join } = require('path');
const { formSource, readLiteral, readSetLiteral } = require('./catalog/form-menu-source');
const { catalogSnapshot, generateFormBundle, serialize } = require('./catalog/generate-form-bundle');
const { composeServedMenu, CARRIED_FROM_STRUCTURE } = require('./catalog/public-menu');

// PLAN 4 GATED (G1): the bootstrap's record set = the form literals + the ONE reviewed data file's rows (reward_icon / extras_policy)
const { withBootstrapRows } = require('./catalog/menu-structure-rows');
const BR = (rid, src) => withBootstrapRows(rid, { dishes: readLiteral(src, 'MENU'), extras: readLiteral(src, 'EXTRAS') });

let n = 0; const ok = (l) => console.log(`  ✓ ${++n} ${l}`);
const REPO_ROOT = join(__dirname, '..');
const BUNDLE_PATH = {
  x_pizza: join(REPO_ROOT, 'xpizza-orders', 'menu-bundle.generated.json'),
  la_musa: join(REPO_ROOT, 'la-musa-orders', 'menu-bundle.generated.json'),
};

// ── 1. FULL-SHAPE + ORDER PARITY: generated bundle == the form arrays, both brands ─────────────────
for (const rid of ['x_pizza', 'la_musa']) {
  const src = formSource(rid);
  const bundle = generateFormBundle(rid, catalogSnapshot(rid));
  assert.deepStrictEqual(bundle.dishes, BR(rid, src).dishes,
    `${rid}: generated dish array must equal the form's MENU field-for-field AND in order`);
  ok(`bundle parity ${rid}: ${bundle.dishes.length} dishes generated byte-identical to the form (fields + order)`);
}
{
  const src = formSource('la_musa');
  const bundle = generateFormBundle('la_musa', catalogSnapshot('la_musa'));
  assert.deepStrictEqual(bundle.categories, readLiteral(src, 'CATEGORIES'), 'la_musa categories (order/labels/subcats/layout)');
  assert.deepStrictEqual(bundle.variant_items, readLiteral(src, 'VARIANT_ITEMS', '{', '}'), 'la_musa VARIANT_ITEMS');
  assert.deepStrictEqual(bundle.has_photo, readSetLiteral(src, 'HAS_PHOTO').slice().sort(), 'la_musa HAS_PHOTO set');
  ok(`bundle parity la_musa: ${bundle.categories.length} categories (w/ subcats+layout), variants, ${bundle.has_photo.length}-item photo set`);
}
{
  const src = formSource('x_pizza');
  const bundle = generateFormBundle('x_pizza', catalogSnapshot('x_pizza'));
  assert.deepStrictEqual(bundle.pickup_only_cats, readLiteral(src, 'PICKUP_ONLY_CATS'), 'x_pizza PICKUP_ONLY_CATS');
  assert.deepStrictEqual(bundle.weekend_only_cats, readLiteral(src, 'WEEKEND_ONLY_CATS'), 'x_pizza WEEKEND_ONLY_CATS');
  const catOrder = []; for (const d of readLiteral(src, 'MENU')) if (!catOrder.includes(d.cat)) catOrder.push(d.cat);
  assert.deepStrictEqual(bundle.categories.map((c) => c.id), catOrder, 'x_pizza category order preserved');
  ok('bundle parity x_pizza: category order + PICKUP_ONLY / WEEKEND_ONLY gate cats carried');
}

// ── 2. COMMITTED ARTIFACT: the checked-in bundle is exactly what generation produces (not stale) ───
for (const rid of ['x_pizza', 'la_musa']) {
  const committed = readFileSync(BUNDLE_PATH[rid], 'utf8');
  const fresh = serialize(composeServedMenu(rid, catalogSnapshot(rid)));   // PLAN 4 (A): the committed bundle is the PUBLISHED shape
  assert.strictEqual(committed, fresh,
    `${rid}: committed menu-bundle.generated.json is stale — re-run \`node generate-form-bundle.mjs\``);
  // and the committed bytes really carry the whole form menu (byte-parity down to the actual file)
  assert.deepStrictEqual(JSON.parse(committed).dishes, BR(rid, formSource(rid)).dishes,
    `${rid}: committed bundle dishes == the form MENU (byte parity of the shipped artifact)`);
  ok(`committed artifact ${rid}: menu-bundle.generated.json == fresh generation == the form MENU`);
}

// ── 2b. PLAN 4 (gap resolution A) — the committed bundle takes the PUBLISHED shape, and the shape change is VALUES-EQUAL ──
//    The composed carried fields are exactly today's literals (the forms then boot them from the bundle, not the literal),
//    and everything else is the generator's bundle, unchanged.
{
  const lm = composeServedMenu('la_musa', catalogSnapshot('la_musa')); const lsrc = formSource('la_musa');
  assert.deepStrictEqual(lm.extras, BR('la_musa', lsrc).extras, 'la_musa extras == the EXTRAS literal (+ the reviewed rows)');
  assert.deepStrictEqual(lm.extras_by_category, readLiteral(lsrc, 'EXTRAS_BY_CATEGORY', '{', '}'), 'la_musa extras_by_category == EXTRAS_BY_CATEGORY');
  assert.deepStrictEqual(lm.extras_by_item, readLiteral(lsrc, 'EXTRAS_BY_ITEM', '{', '}'), 'la_musa extras_by_item == EXTRAS_BY_ITEM');
  assert.deepStrictEqual(lm.badges, readLiteral(lsrc, 'TAG_BADGES', '{', '}'), 'la_musa badges == TAG_BADGES');
  assert.deepStrictEqual(lm.badge_priority, require('./tools/migrations/2026-10-26-menu-structure.json').restaurants.la_musa.structure.badge_priority, 'PLAN 4 GATED (G1): the bootstrap carries the reviewed badge_priority');
  const xp = composeServedMenu('x_pizza', catalogSnapshot('x_pizza')); const xsrc = formSource('x_pizza');
  assert.deepStrictEqual(xp.extras, BR('x_pizza', xsrc).extras, 'x_pizza extras == the EXTRAS literal (+ the reviewed rows)');
  // x_pizza has no map literal: its renderer offers EVERY extra category, in EXTRAS order, to every dish category
  const allCats = [...new Set(readLiteral(xsrc, 'EXTRAS').map((e) => e.cat))];
  assert.deepStrictEqual(xp.extras_by_category, Object.fromEntries(xp.categories.map((c) => [c.id, allCats])), 'x_pizza extras_by_category == every extra category for every dish category (today\'s renderer)');
  for (const rid of ['x_pizza', 'la_musa']) {
    const composed = composeServedMenu(rid, catalogSnapshot(rid)); const gen = generateFormBundle(rid, catalogSnapshot(rid));
    const extra = Object.keys(composed).filter((k) => !(k in gen));
    assert.ok(extra.every((k) => CARRIED_FROM_STRUCTURE.includes(k)), `${rid}: only carried fields are added (${extra})`);
    for (const k of Object.keys(gen)) assert.deepStrictEqual(composed[k], gen[k], `${rid}: ${k} is the generator's, unchanged`);
  }
  ok('committed bundle = the published shape: the generator\'s fields unchanged + carried fields VALUE-EQUAL to today\'s literals (la_musa EXTRAS_BY_* / TAG_BADGES; x_pizza every-category map)');
}

// ── 3. NON-VACUITY + SENTINEL: a change to the snapshot RECORDS flows into the bundle ──────────────
//    Proves the generator is driven by its { items, structure } INPUT — mutating a snapshot record
//    changes the bundle — not by a re-read of the form. NOTE: the snapshot here is the bootstrap
//    (catalogSnapshot → buildCatalogV2), so this proves RECORD-driven generation, NOT live-catalog-store
//    provenance; that (a value seeded ONLY into Firestore) is the emulator test's job.
{
  const snap = catalogSnapshot('la_musa');
  const mutated = {
    ...snap,
    items: snap.items.map((it, idx) => (idx === 0
      ? { ...it, display: { ...it.display, name: 'SENTINEL DISH', desc: 'catalog-only text' } } : it)),
  };
  const bundle = generateFormBundle('la_musa', mutated);
  assert.strictEqual(bundle.dishes[0].name, 'SENTINEL DISH', 'a catalog-only display value must surface in the bundle');
  assert.strictEqual(bundle.dishes[0].desc, 'catalog-only text');
  assert.notStrictEqual(readLiteral(formSource('la_musa'), 'MENU')[0].name, 'SENTINEL DISH', 'the form does NOT carry the sentinel');
  ok('non-vacuity: a snapshot-record change drives the bundle (generation is record-driven, not a form re-read)');
}
{
  // order is data: permuting item_order permutes the bundle.
  const snap = catalogSnapshot('x_pizza');
  const flipped = { ...snap, structure: { ...snap.structure,
    item_order: [snap.structure.item_order[1], snap.structure.item_order[0], ...snap.structure.item_order.slice(2)] } };
  const bundle = generateFormBundle('x_pizza', flipped);
  assert.strictEqual(bundle.dishes[0].name, snap.structure.item_order[1], 'item_order drives the emitted dish order');
  ok('non-vacuity: item_order actually drives the generated dish order');
}

// ── 4. DETERMINISM: generating twice from the same catalog yields byte-identical artifacts ─────────
for (const rid of ['x_pizza', 'la_musa']) {
  const a = serialize(generateFormBundle(rid, catalogSnapshot(rid)));
  const b = serialize(generateFormBundle(rid, catalogSnapshot(rid)));
  assert.strictEqual(a, b, `${rid}: two generations must be byte-identical (deterministic)`);
  ok(`determinism ${rid}: two independent generations are byte-identical`);
}

console.log(`catalog-form-bundle: OK (${n})`);
